const p=(key,label,min,max,value)=>({key,label,min,max,value,step:1});
export const ART_EFFECTS={oilpaint:{name:'油画色块',cat:'印刷',icon:'▰',desc:'局部主色笔触与色阶归并',params:[p('radius','笔触半径',1,5,3),p('amount','混合强度',0,100,80)]},woodprint:{name:'浮世绘木版',cat:'印刷',icon:'◩',desc:'矿物色限色、深色轮廓与纸纹模拟',params:[p('edge','轮廓浓度',0,100,60),p('amount','混合强度',0,100,85)]}};
export function applyArt(c,e){const x=c.getContext('2d'),im=x.getImageData(0,0,c.width,c.height),a=im.data,b=new Uint8ClampedArray(a),w=c.width,h=c.height,m=e.params.amount/100;if(!m)return c;const lum=i=>b[i]*.299+b[i+1]*.587+b[i+2]*.114;const palette=[[28,49,64],[57,94,111],[103,134,129],[178,75,53],[203,159,91],[230,214,175]];const r=Math.max(1,Math.round(e.params.radius*w/1200));for(let y=0;y<h;y++)for(let xx=0;xx<w;xx++){const i=(y*w+xx)*4;if(!b[i+3])continue;let color;if(e.type==='oilpaint'){const bins=Array.from({length:8},()=>[0,0,0,0]);for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){const j=(Math.max(0,Math.min(h-1,y+dy))*w+Math.max(0,Math.min(w-1,xx+dx)))*4;if(!b[j+3])continue;const z=bins[Math.min(7,Math.floor(lum(j)/32))];z[0]++;for(let k=0;k<3;k++)z[k+1]+=b[j+k];}const best=bins.reduce((a,b)=>a[0]>=b[0]?a:b);color=best.slice(1).map(v=>v/best[0]);}else{color=palette.reduce((best,col)=>{const d=z=>z.reduce((s,v,k)=>s+(v-b[i+k])**2,0);return d(col)<d(best)?col:best});const edge=(Math.abs(lum(i)-lum((y*w+Math.min(w-1,xx+1))*4))+Math.abs(lum(i)-lum((Math.min(h-1,y+1)*w+xx)*4)))/255*e.params.edge/100;const grain=(((xx*13+y*7)%17)-8)*.6;color=color.map(v=>v*(1-Math.min(.8,edge))+grain);}for(let k=0;k<3;k++)a[i+k]=b[i+k]*(1-m)+color[k]*m;}x.putImageData(im,0,0);return c;}
